import { Address as AddressSchema } from "../schemas.js";
import { object, z } from "../zod.js";
import type { Address } from "viem";

export const EIP_7702_ACCOUNT_TYPE = ["ModularAccountV2"] as const;

export type Supported7702AccountType = (typeof EIP_7702_ACCOUNT_TYPE)[number];

export const Eip7702AccountTypeToDelegationAddress = {
  ModularAccountV2: "0x69007702764179f14F51cdce752f4f775d74E139",
} as const satisfies Record<Supported7702AccountType, Address>;

export const SUPPORTED_DELEGATION_ADDRESSES = [
  ...Object.values(Eip7702AccountTypeToDelegationAddress),
  "0x0000000000000000000000000000000000000000" as const,
] as const;

export const Eip7702AuthCapability = z.union([
  object(
    {
      account: AddressSchema().optional(),
      // Wallet applications must maintain a strict shortlist of well-known accounts.
      // https://github.com/ethereum/ERCs/pull/947/files#diff-dab085f963ca621595044bcbc0922705aa38b69f5bf8770dcb3d0496a633efcfR189
      delegation: z.union([
        z.enum(EIP_7702_ACCOUNT_TYPE),
        z.enum(SUPPORTED_DELEGATION_ADDRESSES),
      ]),
    },
    {
      description: "Specify EIP-7702 delegation",
    },
  ),
  z.literal(true).meta({
    description:
      "Use default EIP-7702 delegation (Note: EIP-7702 is enabled by default unless you first call `wallet_requestAccount` to get a smart contract address.)",
  }),
]);

export type Eip7702AuthCapability = z.input<typeof Eip7702AuthCapability>;

export const DelegationAddressToAccountType: Record<
  Address,
  Supported7702AccountType
> = Object.fromEntries(
  Object.entries(Eip7702AccountTypeToDelegationAddress).map(([key, value]) => [
    value,
    key,
  ]),
) as Record<Address, Supported7702AccountType>;

export const getAccountTypeForDelegationAddress7702 = (
  address: Address,
): Supported7702AccountType | undefined => {
  return DelegationAddressToAccountType[address];
};
